import heapq
import sys

low, high = [], []  # the smaller half negated, and the larger half
for line in sys.stdin:
    parts = line.split()
    if parts[0] == "add":
        t = int(parts[1])
        heapq.heappush(low, -t)
        heapq.heappush(high, -heapq.heappop(low))
        if len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
    elif low:
        print(-low[0])
    else:
        print("no waits")
